{"command": "python3 -c "
from PIL import Image, ImageDraw
im=Image.open('radiograph.jpg').convert('L')
def gc(x1,y1,x2,y2,name,sc=3):
    c=im.crop((x1,y1,x2,y2)); c=c.resize((int(c.size[0]*sc),int(c.size[1]*sc)),Image.LANCZOS)
    d=ImageDraw.Draw(c)
    for y in range(y1,y2,20):
        d.line([(0,(y-y1)*sc),(c.size[0],(y-y1)*sc)],fill=255,width=1); d.text((3,(y-y1)*sc+2),str(y),fill=255)
    for x in range(x1,x2,25):
        d.line([((x-x1)*sc,0),((x-x1)*sc,c.size[1])],fill=100,width=1); d.text(((x-x1)*sc+2,3),str(x),fill=255)
    c.save(name); print(name,c.size)
gc(400,480,720,720,'raw_upR.png')
